head.script:
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo, scwin.vListBzSeq, scwin.vListProcsStatCd;
scwin.TR_JOB;
scwin.rowPos;
scwin.mktTpCd; //거래시장구분 1= 유가, 2=코스닥
//let gAfStdIndCd = "";

scwin.strCbd_SME_YN = [{ value: 'N', text: '아님' },{ value: 'Y', text: '중소기업' }];
scwin.strCbd_HDCOM_YN = [{ value: 'N', text: '관련없음' },{ value: 'Y', text: '지주회사' }];
scwin.strCbd_NPARVALSTK_YN = [{ value: 'N', text: '아니오' },{ value: 'Y', text: '예' }];
scwin.vScrenID = "ULDSTF05101.xml";

scwin.BTN_MAP = {
    "save" : "btn_Save",       // [저장]
    "modify" : "btn_Update",      // [수정]
};


scwin.onpageload = function() {
    scwin.userInfo = $c.session.getUserInfo(); 
    scwin.init();
};

scwin.init = async function() {
    let parentWin = $c.win.getParent();
    scwin.vBzProcsNo = parentWin.scwin.clickBzProcsNo;
    scwin.vListBzSeq = parentWin.scwin.clickListBzSeq;
    scwin.mktTpCd = $c.stf.getObjectValue(parentWin.rdo_SPOT_ISU_TRD_MKT_TP_CD);
    scwin.rowPos = parentWin.dlt_List.getRowPosition();

    await scwin.fn_SetComboCode();
    if (scwin.vBzProcsNo != "") {
        scwin.fn_read_sync();
        cmb_SECUGRP_ID.setDisabled(true);
    } else {
        scwin.fn_initForm("C");
        $c.stf.setObjectValue(cmb_SECUGRP_ID, $c.stf.getObjectValue(parentWin.cmb_NEW_SECUGRP_ID));
        scwin.fn_changeForm("01"); //초기값-심사진행

        chk_WEB_DP_YN.setValue((dma_Item.get("webDpYn") == "N"));
        chk_WEB_NOPN_YN.setValue((dma_Item.get("webNopnYn") == "Y"));

        if ($c.stf.getObjectValue(cmb_NPARVALSTK_YN) == "Y") {
            edt_PARVAL.hide();
            lb_PARVAL.hide();
            edt_PER1STK_CAP.show();
            lb_PER1STK_CAP.show();
        } else {
            edt_PARVAL.show();
            lb_PARVAL.show();
            edt_PER1STK_CAP.hide();
            lb_PER1STK_CAP.hide();
        }

        if (scwin.vBzProcsNo == "") {
            $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);

            scwin.fn_initForm('C');
        } 

        if (scwin.userInfo.depCd != '2500' && scwin.userInfo.depCd != '2520' && scwin.userInfo.depCd != '2540' &&
            scwin.userInfo.depCd != '3300' && scwin.userInfo.depCd != '3320' && scwin.userInfo.depCd != '3330' &&
            scwin.userInfo.depCd != '3E00' && scwin.userInfo.depCd != '3E10' && scwin.userInfo.depCd != '3E20' && scwin.userInfo.depCd != '3E30' && scwin.userInfo.depCd != '3E40' &&
            scwin.userInfo.depCd != '2615' && scwin.userInfo.depCd != '3G20') {
            //심사1팀,심사2팀
            $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
        }
    }

    scwin.fn_initLabel($c.stf.getObjectValue(cmb_SECUGRP_ID));
};



