	function fn_SetComboCode2() {
	let h = "VALUE:string,TEXT:string";
		dts_C_All.SetDataHeader(h);
		dts_C_All.AddRow();
		cmb_SME_YN.AddData("6^CCA");
		cmb_SME_YN.AddData("7^CCA");
	}

	function fn_SetComboCode3(mxcombo) {
		alert("[ELEMENT_ID :"+mxcombo.id);
	}
**************************/

scwin.fn_SetComboCode = async function() {
    dlt_SME_YN.setJSON(scwin.strCbd_SME_YN);
    dlt_HDCOM_YN.setJSON(scwin.strCbd_HDCOM_YN);
    dlt_NPARVALSTK_YN.setJSON(scwin.strCbd_NPARVALSTK_YN);
    cmb_SME_YN.setNodeSet("data:dlt_SME_YN", "text", "value");
    cmb_HDCOM_YN.setNodeSet("data:dlt_HDCOM_YN", "text", "value");
    cmb_NPARVALSTK_YN.setNodeSet("data:dlt_NPARVALSTK_YN", "text", "value");
    cmb_SME_YN.setSelectedIndex(0);
    cmb_HDCOM_YN.setSelectedIndex(0);
    cmb_NPARVALSTK_YN.setSelectedIndex(0);

    //주거래은행
    const sbmOptions = {
        id: "sbm_list-maintrade-bank",
        method: "get",
        action: "/api/listing/common/code/list-maintrade-bank",
        target: "dlt_MaintrBkCd=body",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success) {
        scwin.fn_searchCode();
    }


};
scwin.fn_searchCode = async function() {
    /*
    00443-통화ISO코드-일반사항-CURR_ISO_CD-cmb_CurrIsoCd
    00443-액면가통화ISO코드-일반사항-PARVAL_CURR_ISO_CD-cmb_ParvalCurrIsoCd
    00443-재무통화ISO코드-일반사항-FNC_CURR_ISO_CD-cmb_CapCurrIsoCd
    00443-공모가통화ISO코드-일반사항-PUBPRC_CURR_ISO_CD-cmb_PubprcCurrIsoCd
    00443-공모가예정통화ISO코드-일반사항-PUBPRC_SCHDL_CURR_ISO_CD-cmb_PubprcSchdlCurrIsoCd
    00685-명의개서대행기관-일반사항-TRANSSTK_AGNT_CD-cmb_TransstkAgntCd
    00755 - 외부감사인코드
    */
    const codeOptions = [
		{
			code: "CURR_ISO_CD",	
			action: "/api/listing/common/code/list-code-value?codeList=CURR_ISO_CD",
			firstRow : ["", ""],
            labelColumn: "text",
            valueColumn: "value",
			compID: "cmb_CURR_ISO_CD"  
		},
        {
			code: "CURR_ISO_CD",	
			action: "/api/listing/common/code/list-code-value?codeList=CURR_ISO_CD",
			firstRow : ["", ""],
            labelColumn: "text",
            valueColumn: "value",
			compID: "cmb_PARVAL_CURR_ISO_CD"  
		},
        {
			code: "CURR_ISO_CD",	
			action: "/api/listing/common/code/list-code-value?codeList=CURR_ISO_CD",
			firstRow : ["", ""],
            labelColumn: "text",
            valueColumn: "value",
			compID: "cmb_FNC_CURR_ISO_CD"  
		},
        {
			code: "CURR_ISO_CD",	
			action: "/api/listing/common/code/list-code-value?codeList=CURR_ISO_CD",
			firstRow : ["", ""],
            labelColumn: "text",
            valueColumn: "value",
			compID: "cmb_PUBPRC_CURR_ISO_CD"  
		},
        {
			code: "CURR_ISO_CD",	
			action: "/api/listing/common/code/list-code-value?codeList=CURR_ISO_CD",
			firstRow : ["", ""],
            labelColumn: "text",
            valueColumn: "value",
			compID: "cmb_PUBPRC_SCHDL_CURR_ISO_CD"  
		},
        {
			code: "CURR_ISO_CD",	
			action: "/api/listing/common/code/list-code-value?codeList=CURR_ISO_CD",
			firstRow : ["", ""],
            labelColumn: "text",
            valueColumn: "value",
			compID: "cmb_NETINCM_CURR_ISO_CD"  
		},
        {
			code: "TRANSSTK_AGNT_CD",	
			action: "/api/listing/common/code/list-code-value?codeList=TRANSSTK_AGNT_CD",
			firstRow : ["", ""],
            labelColumn: "text",
            valueColumn: "value",
			compID: "cmb_TRANSSTK_AGNT_CD"  
		},
        {
			code: "EXT_AUDTR_CD",	
			action: "/api/listing/common/code/list-code-value?codeList=EXT_AUDTR_CD",
			firstRow : ["", ""],
            labelColumn: "text",
            valueColumn: "value",
			compID: "cmb_EXT_AUDTR_CD"  
		}
	];

	await $c.data.setCommonCode(codeOptions);
};

scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_COM_NM.src = "../img/btn_search.gif";
        img_COM_NM.setDisabled(false);
    } else if (initTyp == "X") {
        img_COM_NM.src = "../img/btn_search_d.gif";
        img_COM_NM.setDisabled(true);
    }
};
scwin.fn_initLabel = function(secugrpId) {
    //alert("secugrpId:"+secugrpId);
    lb_LIST_SHRS.setValue("*상장(예정)주식수");
    lb_PARVAL.setValue("액면가");
    lb_PUBOFR_SHRS.setValue("공모주식수");
    label_59.hide();
    label_78.hide();
    label_79.hide();
    label_81.hide();
    edt_NETINCM_AMT1.hide();
    cmb_NETINCM_CURR_ISO_CD.hide();
    if (secugrpId == "FS") {
        panel_foriegn.setDisabled(false);//10.20추가
        panel_foriegn.setReadOnly(false);
        label_47.hide();
        label_80.hide();
        label_78.show();
        label_79.show();
        label_81.show();
        label_dr.show();
        edt_NETINCM_AMT1.show();
        cmb_NETINCM_CURR_ISO_CD.show();
        panel_Forn_Item.show();
        cmb_CURR_ISO_CD.hide();
        edt_PER1DR_FORNSTK_RTO.setDisabled(true);
        if ($c.stf.getObjectValue(cmb_PUBPRC_CURR_ISO_CD) == "") {
            $c.stf.setObjectValue(cmb_PUBPRC_CURR_ISO_CD, "KRW");
        }
        if ($c.stf.getObjectValue(cmb_PUBPRC_SCHDL_CURR_ISO_CD) == "") {
            $c.stf.setObjectValue(cmb_PUBPRC_SCHDL_CURR_ISO_CD, "KRW");
        }
    } else if (secugrpId == "DR") {
        panel_foriegn.setDisabled(false);//10.20추가
        panel_foriegn.setReadOnly(false);
        label_74.hide();
        label_75.hide();
        label_76.hide();
        label_77.hide();
        label_59.show();
        label_dr.show();
        cmb_PARVAL_CURR_ISO_CD.hide();
        cmb_FNC_CURR_ISO_CD.hide();
        cmb_PUBPRC_CURR_ISO_CD.hide();
        cmb_PUBPRC_SCHDL_CURR_ISO_CD.hide();
        cmb_NETINCM_CURR_ISO_CD.hide();
        panel_Forn_Item.show();
        edt_PER1DR_FORNSTK_RTO.setDisabled(false);
        lb_LIST_SHRS.setValue("*상장DR수");
        lb_PARVAL.setValue("액면가(원주기준)");
        lb_PUBOFR_SHRS.setValue("공모DR수");
    } else {
        panel_foriegn.setDisabled(true);//10.20추가
        panel_foriegn.setReadOnly(true);
        label_dr.hide();
        panel_Forn_Item.hide();
    }
    edt_LISTDD_CLSPRC.setValue("0");
    edt_FST_BAS_PRC.setValue("0");
};
scwin.fn_GetParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_STD_IND_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_STD_IND_NM); // 명칭값을 포함할 컨트롤

    return arrPar;
};
scwin.fn_SetParStdInd = function(arrPar) {
    /*
    gAfStdIndCd = arrPar[0].STD_IND_CD;
    if (js_market == '1') {
    } else if (js_market == '2') {
    	txb_STD_IND_CD.value = arrPar[0].KOSDAQ_STD_IND_CD;
    }
    */
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD);
    txb_STD_IND_NM.setValue(arrPar[0].IND_NM);
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    arrPar[3] = scwin.mktTpCd;
    arrPar[4] = $c.lc.SEARCH_TYP_SEC; //신규등록시

    return arrPar;
};
scwin.fn_SetParIsur = async function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        /*if(arrPar[0].LIST_DD == ""){
            alert('보통주 등록이 선행되어야 합니다');
        	return;
        }*/

        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        txb_COM_ENG_NM.setValue(arrPar[0].COM_ENG_NM);
        txb_CMSTK_LIST_DD.setValue(arrPar[0].LIST_DD);
        scwin.vListBzSeq = arrPar[0].LIST_BZ_SEQ;

        if ($c.stf.getObjectValue(txb_ISUR_CD) != "") {
            dma_Item.setEmptyValue();

            let reqMap = {
                isurCd: arrPar[0].ISUR_CD,
                listBzSeq : scwin.vListBzSeq
            };

            const sbmOptions = {
                id: "sbm_selectcominfo",
                action: "/api/listing/lstproc/kind/prelisting-kindstk/select-com-info",
                method: "get",
                target: "dma_Item=body",
                isProcessMsg: false
            };

            const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
            if (res.responseJSON.success) {
                if ($c.util.isEmpty(dma_Item.get("secugrpId"))) {
                    let parentWin = $c.win.getParent();
                    dma_Item.set("secugrpId", $c.stf.getObjectValue(parentWin.cmb_NEW_SECUGRP_ID));
                }
            }

        }
    }
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = scwin.mktTpCd;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_NM);
    }
};
scwin.fn_SetParForIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_NM);
};
scwin.fn_read_sync = async function() {
    //alert("LIST_BZ_SEQ :"+vListBzSeq);

    let reqMap = {
        bzProcsNo: scwin.vBzProcsNo,
        listBzSeq : scwin.vListBzSeq,
        spotIsuTrdMktTpCd : scwin.mktTpCd
    };
    const sbmOptions = {
        id: "sbm_select",
        action: "/api/listing/lstproc/kind/prelisting-kindstk/select-one",
        method: "get",
        target: "dma_Item=body",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
    if (res.responseJSON.success) {
        dma_Item.set("bzProcsNo", scwin.vBzProcsNo);
        dma_Item.set("listBzSeq", scwin.vListBzSeq);
        scwin.fn_changeForm(dma_Item.get("invstgProgStatCd"));

        chk_WEB_DP_YN.setValue(dma_Item.get("webDpYn") == "N" ? "Y" : "N");
        chk_WEB_NOPN_YN.setValue(dma_Item.get("webNopnYn") == "Y" ? "Y" : "N");

        if ($c.stf.getObjectValue(cmb_NPARVALSTK_YN) == "Y") {
            edt_PARVAL.hide();
            lb_PARVAL.hide();
            edt_PER1STK_CAP.show();
            lb_PER1STK_CAP.show();
        } else {
            edt_PARVAL.show();
            lb_PARVAL.show();
            edt_PER1STK_CAP.hide();
            lb_PER1STK_CAP.hide();
        }
        if (scwin.vBzProcsNo == "") {
            $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
            scwin.fn_initForm('C');
        } else {
            scwin.fn_initForm('X');
            $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
        }

        if (scwin.userInfo.depCd != '2500' && scwin.userInfo.depCd != '2520' && scwin.userInfo.depCd != '2540' &&
            scwin.userInfo.depCd != '3300' && scwin.userInfo.depCd != '3320' && scwin.userInfo.depCd != '3330' &&
            scwin.userInfo.depCd != '3E00' && scwin.userInfo.depCd != '3E10' && scwin.userInfo.depCd != '3E20' && scwin.userInfo.depCd != '3E30' && scwin.userInfo.depCd != '3E40' &&
            scwin.userInfo.depCd != '2615' && scwin.userInfo.depCd != '3G20') {
            //심사1팀,심사2팀
            $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
        }
    }

};
scwin.strCbd_INVSTG_PROG_STAT_CD_1 = [{ value: '01', text: '심사진행' },{ value: '02', text: '심사완료' },{ value: '03', text: '심사완료(6개월경과등)' },{ value: '04', text: '심사연기' },{ value: '05', text: '심사철회' },{ value: '06', text: '심사기각' }];
scwin.strCbd_INVSTG_PROG_STAT_CD_2 = [{ value: '10', text: '신규상장 - 비상장' },{ value: '11', text: '신규상장 - 코스닥법인' },{ value: '21', text: '재상장 - 인적분할' },{ value: '22', text: '재상장 - 폐지' },{ value: '23', text: '재상장 - 합병' },{ value: '24', text: '재상장 - 물적분할' }];
scwin.fn_changeForm = function(gStatCd) {
    //alert("[gStatCd]:"+gStatCd);
    //alert("[gStatCd.charAt(0) ]:"+gStatCd.charAt(0) );
    if (gStatCd != "" && gStatCd.charAt(0) != '0') {
        cmb_INVSTG_PROG_STAT_CD.setDisabled(false);
        dlt_invstgProgStatCd.setJSON(scwin.strCbd_INVSTG_PROG_STAT_CD_2);
        cmb_INVSTG_PROG_STAT_CD.setNodeSet("data:dlt_invstgProgStatCd", "text", "value");
    } else {
        cmb_INVSTG_PROG_STAT_CD.setDisabled(false);
        dlt_invstgProgStatCd.setJSON(scwin.strCbd_INVSTG_PROG_STAT_CD_1);
        cmb_INVSTG_PROG_STAT_CD.setNodeSet("data:dlt_invstgProgStatCd", "text", "value");
    }
    cmb_INVSTG_PROG_STAT_CD.setValue(gStatCd);
};
scwin.fn_getLeadComNoStr = function() {
    return dma_Item.get("leadcomMbrNmStr");
};
scwin.fn_setLeadComNMStr = function(str_no, str_nm) {
    dma_Item.set("leadcomMbrNoStr", str_no);
    dma_Item.set("leadcomMbrNmStr", str_nm);
    txb_LEADCOM_MBR_NM_STR.setValue(str_nm);
    //alert("[str_no] :"+str_no);

};

scwin.fn_CheckForm = async function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        await $c.win.alert("[법인]을 선택하세요.");
        img_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_NM) == "") {
        await $c.win.alert("[한글법인명]을 입력하세요..");
        txb_COM_NM.focus();
        return false;
    }

    //2009.05.12 법인명의 '주식회사' 를 '(주)'로 변경, '(주)'가 없는 법인인 경우 입력하도록..(국내법인인 경우만)
    if (dma_Item.get("secugrpId") == "ST") {
        //alert("[SECUGRP_ID] :"+dma_Item.NameValue(1,"SECUGRP_ID"));
        let tmpComNm_pre = $c.stf.getObjectValue(txb_COM_NM);
        let tmpComNm_next = tmpComNm_pre.replace('주식회사', '');
        if (tmpComNm_pre != tmpComNm_next) {
            await $c.win.alert("한글회사명에 '주식회사'는 '(주)'로 입력, 영문회사명에 'CO.,LTD' 를 입력하세요");
            txb_COM_NM.focus();
            return false;
        }
        tmpComNm_pre = $c.stf.getObjectValue(txb_COM_NM);
        tmpComNm_next = tmpComNm_pre.replace('(주)', '');
        if (tmpComNm_pre == tmpComNm_next) {
            await $c.win.alert("한글회사명에 '(주)' 를 입력하세요");
            txb_COM_NM.focus();
            return false;
        }
    }

    if ($c.stf.getObjectValue(txb_COM_ENG_NM) == "") {
        await $c.win.alert("[영문법인명]을 입력하세요..");
        txb_COM_ENG_NM.focus();
        return false;
    }
    if (chk_WEB_DP_YN.getValue() == "Y" && chk_WEB_NOPN_YN.getValue() == "Y") {
        await $c.win.alert("[비공개 심사시 선택] 와 [비공개(인적분할 재상시)]를 중복으로 선택하실수 없습니다.");
        chk_WEB_DP_YN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_INVSTG_BILL_ACPT_DD) == "") {
        //alert("[청구서접수일]를 입력하세요.");edt_INVSTG_BILL_ACPT_DD.focus();return false;

    }
    if ($c.stf.getObjectValue(txb_APPL_COM_CHRG_NM) == '') {
        await $c.win.alert('신청회사 담당자명을 입력하십시오');
        txb_APPL_COM_CHRG_NM.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_APPL_COM_CHRG_TEL_NO) == "") {
        await $c.win.alert('담당자 연락처를 입력하십시오');
        txb_APPL_COM_CHRG_TEL_NO.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_INVSTG_PROG_STAT_CD) == "02" && $c.stf.getObjectValue(edt_INVSTG_COMPLT_DD) == "") {
        //alert("[심사결과확정일]을 선택하십시오. \n상장구분이 심사완료인 경우 등록필수항목입니다.");edt_INVSTG_COMPLT_DD.focus();return false;

    }
    if ($c.stf.getObjectValue(cmb_INVSTG_PROG_STAT_CD) == "") {
        await $c.win.alert("[심사상태]을 선택하세요.");
        cmb_INVSTG_PROG_STAT_CD.focus();
        return false;
    }

    //alert("[parseInt(txb_LIST_SHRS.value,10)."+parseInt(txb_LIST_SHRS.value,10));
    if (parseInt($c.stf.getObjectValue(edt_LIST_SHRS), 10) <= 0 || $c.stf.getObjectValue(edt_LIST_SHRS).length == 0) {
        //alert("[상장(예정)주식수]를 입력하세요.");edt_LIST_SHRS.focus(); return false;

    }
    if (dma_Item.get("secugrpId") == "FS") {
        if ($c.stf.getObjectValue(edt_NETINCM_AMT).length == 0) {
            await $c.win.alert("[당기순이익(원화)]를 입력하세요.");
            edt_NETINCM_AMT.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_NETINCM_AMT1).length == 0) {
            await $c.win.alert("[당기순이익(외화)]를 입력하세요.");
            edt_NETINCM_AMT1.focus();
            return false;
        }
        // 통화 필수체크
        if ($c.stf.getObjectValue(cmb_PARVAL_CURR_ISO_CD) == "") {
            //alert("[액면가 통화표시]를 입력하세요.");cmb_PARVAL_CURR_ISO_CD.focus();return false;

        }
        if ($c.stf.getObjectValue(cmb_NETINCM_CURR_ISO_CD) == "") {
            await $c.win.alert("[당기순이익(외화) 통화표시]를 입력하세요.");
            cmb_NETINCM_CURR_ISO_CD.focus();
            return false;
        }
    } else {
        if ($c.stf.getObjectValue(edt_NETINCM_AMT).length == 0) {
            await $c.win.alert("[당기순이익]을 입력하세요.");
            edt_NETINCM_AMT.focus();
            return false;
        }
    }

    //if ($c.stf.getObjectValue(txb_CNTR_ISO_NM) == "410") {
    if ($c.stf.getObjectValue(txb_CNTR_ISO_CD) == "410") {
        if (parseInt($c.stf.getObjectValue(edt_PARVAL), 18) <= 0 || $c.stf.getObjectValue(edt_PARVAL).length == 0) {
            await $c.win.alert("[액면가]를 입력하세요.");
            edt_PARVAL.focus();
            return false;
        }
    }

    if($c.util.isEmpty(txb_ISU_NM.getValue())){
        await $c.win.alert("[종목명명]를 입력하세요.");
        txb_ISU_NM.focus();
    }


    return true;
};

scwin.fn_save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.fn_CheckForm()) {
        if (! await $c.lc.isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();
        if ($c.str.getByteLength(scwin.vBzProcsNo.toString()) != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dma_Item.set("bzProcsNo", scwin.vBzProcsNo);
            scwin.fn_trs();
        }
    }
};
scwin.fn_update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.fn_CheckForm()) {
        if (! await $c.lc.isProcess(scwin.TR_JOB)) return; 
        scwin.fn_trs();
    }
};
scwin.fn_trs = async function() {
    let vScrenProcTpCd;
    let id;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = $c.stf.SCREN_PROCS_TP_CD_02;
        id = "insert";
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = $c.stf.SCREN_PROCS_TP_CD_03;
        id = "update";
    } 
    dma_Item.set("examprnEmpNo", scwin.userInfo.empNo);
    dma_Item.set("fstExamprnEmpNo", scwin.userInfo.empNo);
    dma_Item.set("webDpYn", (chk_WEB_DP_YN.getValue() == "Y" ? "N" : "Y")); //반대로 체크한다.. 
    dma_Item.set("webNopnYn", (chk_WEB_NOPN_YN.getValue() == "Y" ? "Y" : "N"));
    dma_Item.set("spotIsuTrdMktTpCd", scwin.mktTpCd);

    const sbmOptions = {
        id: "sbm_prelisting-kindstk-" + id,
        action: "/api/listing/lstproc/kind/prelisting-kindstk/" + id,
        mediatype: "application/json",
        method: "post",
        ref: 'data:json,dma_Item',
        target: "data:json",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success) {
        if(res.responseJSON.body.result == "S"){            
            await $c.win.alert($c.data.getMessage("com_complete_0150", "저장"));//": "$[0] 처리 성공하였습니다.",
            await scwin.fn_read_sync();
            scwin.fn_parentRefresh();
            if (scwin.TR_JOB == "U") {
                let parentWin = $c.win.getParent();
                parentWin.dlt_List.getRowPosition(scwin.rowPos);
            }
        }else{
            //com_complete_0151": "$[0] 처리 실패하였습니다.",
            await $c.win.alert($c.data.getMessage("com_complete_0151", "저장"));
        }
    }else{
        await $c.win.alert($c.data.getMessage("com_complete_0151", "저장"));
    }

};
scwin.fn_parentRefresh = function() {
    let fr_fn_list_sync = $c.win.getParent().scwin.fn_list_sync;
    fr_fn_list_sync();
};



