        id: "ULDSTF05107",
        popupName: winTitle,
        width: 800,
        height: 750,
        frameModal: "top",
        type: "pageFramePopup",
    };

    const param = { 
        "secugrpId": $c.win.getParent().rdo_SECUGRP_ID.getValue(),
        "mktTpCd": $c.win.getParent().rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue(),
        "searchType" : "SER"
    };
    const res = await $c.win.openPopup("/ui/lst/kindstk/ULDSTF05107.xml", opts, param);
    txb_ISU_CD.setValue(res.ISU_CD);
    txb_ISU_NM.setValue(res.ISU_NM);
};

