scwin.cmb_NPARVALSTK_YN_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_NPARVALSTK_YN) == "Y") {
        edt_PARVAL.hide();
        lb_PARVAL.hide();
        edt_PER1STK_CAP.show();
        lb_PER1STK_CAP.show();
        $c.stf.setObjectValue(edt_PARVAL, "0");
    } else {
        edt_PARVAL.show();
        lb_PARVAL.show();
        edt_PER1STK_CAP.hide();
        lb_PER1STK_CAP.hide();
        $c.stf.setObjectValue(edt_PER1STK_CAP, "0");
    }
};
